B.bau=s(["El sal\xf3n de clases est\xe1 limpio.","L\u1edbp h\u1ecdc s\u1ea1ch s\u1ebd."],t.s)
B.b_I=s(["El m\xe9dico me revisa.","B\xe1c s\u0129 kh\xe1m b\u1ec7nh cho t\xf4i."],t.s)
